import React from 'react'
import Table from 'react-bootstrap/Table'
import Button from 'react-bootstrap/Button'
import Form from 'react-bootstrap/Form'
import Spinner from 'react-bootstrap/Spinner'

const TableHeader = () => {
  return (
    <thead>
      <tr>
        <th>Commenter</th>
        <th>Messaged Before</th>
        <th>Send Message</th>
      </tr>
    </thead>
  )
}

const TableBody = props => {
  const rows = props.commenters.map((row, index) => {
    return (
      <tr key={index}>
        <td><a target='_blank' rel="noopener noreferrer" href={row.commenterUrl}>{row.commenterUrl}</a></td>
        <td></td>
        <td><Form.Group><Form.Check type="checkbox" /></Form.Group></td>
      </tr>
    )
  })

  return <tbody>{rows}</tbody>
}

const CommentersTable = props => {
  
  const { commenters } = props
  
  const showCommentersTable = props.showCommentersTable ? {display: 'block'} : {display: 'none'};
  
  const showSubmitButton = props.showSubmitButton ? {display: 'block'} : {display: 'none'};
  const showSubmitLoadingButton = props.showSubmitLoadingButton ? {display: 'block'} : {display: 'none'};
        
        
  return (
    <Form>
      <Table style={showCommentersTable}>
        <TableHeader />
        <TableBody commenters={commenters} />
      </Table>
      
       <Button type="submit" value="Submit" onClick={e => {e.preventDefault(); this.submitForm()}} style={showSubmitButton}>Submit</Button>
            
              <Button variant="primary" disabled style={showSubmitLoadingButton}>
                <Spinner
                  as="span"
                  animation="grow"
                  size="sm"
                  role="status"
                  aria-hidden="true"
                />
                Loading...
              </Button>
              
    </Form>
  )
}
 
          

export default CommentersTable
